# -*- coding: utf-8 -*-
"""Rendert den Sitzungsverlauf als lesbares HTML und als Markdown."""
import json, base64, html, os, re, io, textwrap

QUELLE = "/root/.claude/projects/-home-claude/a7e2528c-db50-5178-81ac-17cea78d192f.jsonl"
