# ---------------------------------------------------------------- Markdown
def md2html(t):
    t = t.replace("\r\n", "\n")
    # Codeblöcke sichern
    blocks = []
    def sichern(m):
        blocks.append(m.group(2))
        return "\x00CODE%d\x00" % (len(blocks) - 1)
    t = re.sub(r"```(\w*)\n(.*?)```", sichern, t, flags=re.S)

    zeilen = t.split("\n")
    raus, i = [], 0
    def inline(s):
        s = html.escape(s)
        s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
        s = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", s)
        s = re.sub(r"(?<![\w*])\*([^*\n]+)\*(?![\w*])", r"<em>\1</em>", s)
        s = re.sub(r"~~([^~]+)~~", r"<del>\1</del>", s)
        s = re.sub(r"\[([^\]]+)\]\(([^)]+)\)", r'<a href="\2">\1</a>', s)
        return s
    while i < len(zeilen):
        z = zeilen[i]
        if re.match(r"^\x00CODE\d+\x00$", z.strip()):
            n = int(re.search(r"\d+", z).group())
            raus.append("<pre><code>%s</code></pre>" % html.escape(blocks[n]))
            i += 1; continue
        if re.match(r"^\s*$", z): i += 1; continue
        if re.match(r"^---+\s*$", z): raus.append("<hr>"); i += 1; continue
        m = re.match(r"^(#{1,6})\s+(.*)$", z)
        if m:
            n = len(m.group(1)); raus.append("<h%d>%s</h%d>" % (min(n+2,6), inline(m.group(2)), min(n+2,6))); i += 1; continue
        if z.lstrip().startswith("|") and i + 1 < len(zeilen) and re.match(r"^\s*\|[\s:|-]+\|\s*$", zeilen[i+1]):
            kopf = [c.strip() for c in z.strip().strip("|").split("|")]
            i += 2; zeil = []
            while i < len(zeilen) and zeilen[i].lstrip().startswith("|"):
                zeil.append([c.strip() for c in zeilen[i].strip().strip("|").split("|")]); i += 1
            raus.append("<div class='tw'><table><thead><tr>" +
                        "".join("<th>%s</th>" % inline(c) for c in kopf) + "</tr></thead><tbody>" +
                        "".join("<tr>" + "".join("<td>%s</td>" % inline(c) for c in r) + "</tr>" for r in zeil) +
                        "</tbody></table></div>")
            continue
        if re.match(r"^\s*>", z):
            teil = []
            while i < len(zeilen) and re.match(r"^\s*>", zeilen[i]):
                teil.append(re.sub(r"^\s*>\s?", "", zeilen[i])); i += 1
            raus.append("<blockquote>%s</blockquote>" % md2html("\n".join(teil))); continue
        if re.match(r"^\s*[-*]\s+", z):
            teil = []
            while i < len(zeilen) and (re.match(r"^\s*[-*]\s+", zeilen[i]) or re.match(r"^\s{2,}\S", zeilen[i] or "")):
                if re.match(r"^\s*[-*]\s+", zeilen[i]): teil.append(re.sub(r"^\s*[-*]\s+", "", zeilen[i]))
                elif teil: teil[-1] += " " + zeilen[i].strip()
                i += 1
            raus.append("<ul>" + "".join("<li>%s</li>" % inline(x) for x in teil) + "</ul>"); continue
        if re.match(r"^\s*\d+\.\s+", z):
            teil = []
            while i < len(zeilen) and (re.match(r"^\s*\d+\.\s+", zeilen[i]) or re.match(r"^\s{2,}\S", zeilen[i] or "")):
                if re.match(r"^\s*\d+\.\s+", zeilen[i]): teil.append(re.sub(r"^\s*\d+\.\s+", "", zeilen[i]))
                elif teil: teil[-1] += " " + zeilen[i].strip()
                i += 1
            raus.append("<ol>" + "".join("<li>%s</li>" % inline(x) for x in teil) + "</ol>"); continue
        teil = []
        while i < len(zeilen) and zeilen[i].strip() and not re.match(r"^(#{1,6}\s|\s*[-*]\s|\s*\d+\.\s|\s*>|\||---+\s*$|\x00CODE)", zeilen[i]):
            teil.append(zeilen[i]); i += 1
        if teil: raus.append("<p>%s</p>" % inline(" ".join(teil)))
        else: i += 1
    return "\n".join(raus)

# ---------------------------------------------------------------- Werkzeuge
def kurz(s, n=90):
    s = " ".join(str(s).split())
    return s if len(s) <= n else s[:n-1] + "…"

def label(name, ein):
    p = ein if isinstance(ein, dict) else {}
    kurzname = name.split("__")[-1]
    if name == "Projects":
        m = p.get("method", "")
        z = p.get("path") or p.get("query") or ""
        return {"project_info": "Projektinfo gelesen", "project_read": "Projektdatei gelesen: %s" % z,
                "project_write": "Projektdatei geschrieben: %s" % z, "project_search": "Projekt durchsucht: %s" % z,
                "project_delete": "Projektdatei gelöscht: %s" % z}.get(m, "Projekt: %s" % m)
    if name == "Bash":         return p.get("description") or kurz(p.get("command", ""))
    if name == "Read":         return "Datei gelesen: %s" % os.path.basename(p.get("file_path", ""))
    if name == "Write":        return "Datei geschrieben: %s" % os.path.basename(p.get("file_path", ""))
    if name == "Edit":         return "Datei geändert: %s" % os.path.basename(p.get("file_path", ""))
    if name == "Glob":         return "Dateisuche: %s" % p.get("pattern", "")
    if name == "Grep":         return "Volltextsuche: %s" % p.get("pattern", "")
    if name == "SendUserFile": return "Datei übergeben: %s" % ", ".join(os.path.basename(x) for x in p.get("files", []))
    if name == "SendUserMessage": return "Nachricht an William"
    if name == "AskUserQuestion": return "Rückfrage: %s" % kurz((p.get("questions") or [{}])[0].get("question", ""))
    if name == "TaskCreate":   return "Aufgabe angelegt: %s" % p.get("subject", "")
    if name == "TaskUpdate":   return "Aufgabe aktualisiert: #%s" % p.get("taskId", "")
    if name == "ToolSearch":   return "Werkzeug nachgeladen: %s" % kurz(p.get("query", ""), 60)
    if "freecad__execute_code" in name:
        erste = next((l.strip(" #") for l in str(p.get("code", "")).split("\n")
                      if l.strip().startswith("#") and len(l.strip()) > 3), "")
        return "FreeCAD: Code ausgeführt%s" % (" — " + kurz(erste, 70) if erste else "")
    if "freecad__get_view" in name:       return "FreeCAD: Ansicht %s" % p.get("view_name", "")
    if "freecad__list_documents" in name: return "FreeCAD: Dokumente aufgelistet"
    if "freecad__get_rpc_status" in name: return "FreeCAD: Verbindung geprüft"
    if "device_list_dir" in name:         return "Ordner gelesen: %s" % p.get("path", "")
    if "device_stage_files" in name:      return "Dateien geholt: %s" % ", ".join(os.path.basename(x) for x in p.get("paths", []))[:120]
    if "device_commit_files" in name:     return "Dateien geschrieben: %s" % ", ".join(os.path.basename(f.get("devicePath","")) for f in p.get("files", []))[:120]
    if "device_request_folder_access" in name: return "Ordnerfreigabe angefragt"
    if "get_device_info" in name:         return "Geräteinfo gelesen"
    return kurzname

def ergebnis_text(blk):
    c = blk.get("content")
    if isinstance(c, str): return c, []
    txt, bl = [], []
    if isinstance(c, list):
        for x in c:
            if x.get("type") == "text": txt.append(x.get("text", ""))
            elif x.get("type") == "image": bl.append(x.get("source", {}).get("data", ""))
    return "\n".join(txt), bl

# ---------------------------------------------------------------- Einlesen
def lade():
    eintraege = []
    for zeile in open(QUELLE, encoding="utf-8"):
        try: e = json.loads(zeile)
        except Exception: continue
        if e.get("type") in ("assistant", "user"): eintraege.append(e)
    return eintraege

def bild_speichern(data, zaehler):
    os.makedirs(BILDER, exist_ok=True)
    roh = base64.b64decode(data)
    name = "bild-%03d.png" % zaehler
    open(os.path.join(BILDER, name), "wb").write(roh)
    return name, roh

def bauen():
    eintraege = lade()
    ergebnisse = {}
    for e in eintraege:
        c = (e.get("message") or {}).get("content")
        if isinstance(c, list):
            for b in c:
                if b.get("type") == "tool_result": ergebnisse[b.get("tool_use_id")] = b
    teile_html, teile_md = [], []
    bildnr = 0
    n_user = n_asst = n_tool = 0
    for e in eintraege:
        m = e.get("message") or {}
        rolle = m.get("role"); c = m.get("content")
        zeit = (e.get("timestamp") or "")[:16].replace("T", " ")
        if isinstance(c, str):
            if c.strip().startswith("<system-reminder>") or c.strip().startswith("<command-"): continue
            c = [{"type": "text", "text": c}]
        if not isinstance(c, list): continue
        if rolle == "user":
            texte, bilder = [], []
            for b in c:
                if b.get("type") == "text":
                    t = b.get("text", "")
                    t = re.sub(r"<system-reminder>.*?</system-reminder>", "", t, flags=re.S)
                    t = re.sub(r"<command-[^>]*>.*?</command-[^>]*>", "", t, flags=re.S)
                    if t.strip(): texte.append(t.strip())
                elif b.get("type") == "image":
                    bildnr += 1
                    name, roh = bild_speichern(b["source"]["data"], bildnr)
                    bilder.append((name, base64.b64encode(roh).decode()))
            if not texte and not bilder: continue
            n_user += 1
            inhalt = md2html("\n\n".join(texte)) if texte else ""
            for name, b64 in bilder:
                inhalt += '<img class="usr" src="data:image/png;base64,%s" alt="%s">' % (b64, name)
            teile_html.append('<div class="turn user"><div class="who">William<span class="ts">%s</span></div>'
                              '<div class="body">%s</div></div>' % (zeit, inhalt))
            teile_md.append("\n\n---\n\n## William  ·  %s\n\n%s" % (zeit, "\n\n".join(texte)) +
                            ("".join("\n\n![%s](bilder/%s)" % (n, n) for n, _ in bilder)))
            continue
        # Assistent
        stueck_h, stueck_m = [], []
        for b in c:
            if b.get("type") == "text":
                t = b.get("text", "").strip()
                if not t: continue
                stueck_h.append('<div class="body">%s</div>' % md2html(t))
                stueck_m.append(t)
            elif b.get("type") == "tool_use":
                n_tool += 1
                nm = b.get("name", "?"); ein = b.get("input", {})
                lab = label(nm, ein)
                res = ergebnisse.get(b.get("id"))
                rtxt, rbilder = ergebnis_text(res) if res else ("", [])
                gek = len(rtxt) > 2200
                anz = rtxt[:2200] + ("\n… (%d Zeichen gekürzt)" % (len(rtxt) - 2200) if gek else "")
                ein_s = json.dumps(ein, ensure_ascii=False, indent=1)
                if len(ein_s) > 2600: ein_s = ein_s[:2600] + "\n… gekürzt"
                bild_h = ""
                for data in rbilder:
                    bildnr += 1
                    name, roh = bild_speichern(data, bildnr)
                    bild_h += '<img class="res" src="data:image/png;base64,%s" alt="%s">' % (
                        base64.b64encode(roh).decode(), name)
                stueck_h.append(
                    '<details class="tool" open><summary><span class="ico"></span>'
                    '<span class="lab">%s</span><span class="tn">%s</span></summary>'
                    '<div class="tin"><div class="cap">Eingabe</div><pre>%s</pre>'
                    '%s%s</div></details>' % (
                        html.escape(lab), html.escape(nm.split("__")[-1]), html.escape(ein_s),
                        ('<div class="cap">Ergebnis</div><pre>%s</pre>' % html.escape(anz)) if anz.strip() else "",
                        bild_h))
                stueck_m.append("> **%s** (`%s`)\n>\n> ```\n%s\n> ```" % (
                    lab, nm.split("__")[-1], textwrap.indent(anz[:800], "> ")))
        if not stueck_h: continue
        n_asst += 1
        teile_html.append('<div class="turn asst"><div class="who">Claude<span class="ts">%s</span></div>%s</div>'
                          % (zeit, "".join(stueck_h)))
        teile_md.append("\n\n### Claude  ·  %s\n\n%s" % (zeit, "\n\n".join(stueck_m)))
    return teile_html, teile_md, dict(user=n_user, asst=n_asst, tool=n_tool, bilder=bildnr)
